    raise ValueError('bad input')
except ValueError as err:
    print('An exception happened:', str(err))

def read_age(text):
    return int(text)

def load(text):
    return read_age(text)

def process(text):
    try:
        return load(text)
    except ValueError as e:
        return 'caught: ' + str(e)

print(process('abc'))

